#include <vector>

class Solution {
public:
    int uniquePathsWithObstaclesCount(std::vector<std::vector<int>>& grid) {
        long long MOD = 1000000007;
        int m = grid.size(), n = grid[0].size();
        if (grid[0][0] == 1 || grid[m - 1][n - 1] == 1) return 0;
        std::vector<std::vector<long long>> dp(m, std::vector<long long>(n, 0));
        dp[0][0] = 1;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    dp[r][c] = 0;
                } else {
                    if (r > 0) dp[r][c] = (dp[r][c] + dp[r - 1][c]) % MOD;
                    if (c > 0) dp[r][c] = (dp[r][c] + dp[r][c - 1]) % MOD;
                }
            }
        }
        return dp[m - 1][n - 1];
    }
};

